// Some portions generated by Claude Code
package org.eclipse.rdf4j.tools.lmdb.bulk;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class DiskSpaceMonitorTest {

	private static final long GIB = 1024L * 1024L * 1024L;

	@TempDir
	Path temporaryDirectory;

	private final List<String> messages = Collections.synchronizedList(new ArrayList<>());
	private final AtomicInteger kills = new AtomicInteger();

	@Test
	void killsTheJvmBelowFiftyGibibytesOfFreeSpace() {
		DiskSpaceMonitor monitor = monitorOver(49 * GIB);

		monitor.check(0L);

		assertThat(kills).hasValue(1);
		assertThat(messages).singleElement().asString().contains("49.0 GiB");
	}

	@Test
	void keepsRunningAtExactlyFiftyGibibytesOfFreeSpace() {
		monitorOver(50 * GIB).check(0L);

		assertThat(kills).hasValue(0);
	}

	@Test
	void checksEverySixtySecondsWhileFreeSpaceIsPlentiful() {
		assertThat(monitorOver(200 * GIB).check(0L)).isEqualTo(60_000L);
		assertThat(monitorOver(100 * GIB).check(0L)).isEqualTo(60_000L);
	}

	@Test
	void checksEverySecondOnceFreeSpaceDropsBelowOneHundredGibibytes() {
		assertThat(monitorOver(100 * GIB - 1).check(0L)).isEqualTo(1_000L);
		assertThat(monitorOver(51 * GIB).check(0L)).isEqualTo(1_000L);
	}

	@Test
	void logsOncePerMinuteEvenWhileCheckingEverySecond() {
		DiskSpaceMonitor monitor = monitorOver(60 * GIB);

		for (long now = 0L; now <= 120_000L; now += 1_000L) {
			assertThat(monitor.check(now)).isEqualTo(1_000L);
		}

		assertThat(messages).hasSize(3);
	}

	@Test
	void logsEveryCheckWhileCheckingEveryMinute() {
		DiskSpaceMonitor monitor = monitorOver(200 * GIB);

		for (long now = 0L; now <= 120_000L; now += 60_000L) {
			monitor.check(now);
		}

		assertThat(messages).hasSize(3);
	}

	@Test
	void reportsTheFreeSpaceAndTheLocationItObserved() {
		monitorOver(150 * GIB).check(0L);

		assertThat(messages).singleElement()
				.asString()
				.contains("150.0 GiB")
				.contains("/dev/test");
	}

	@Test
	void keepsCheckingWhenTheFileStoreCannotBeRead() {
		DiskSpaceMonitor monitor = new DiskSpaceMonitor(messages::add, kills::incrementAndGet, () -> {
			throw new IOException("file store unavailable");
		});

		assertThat(monitor.check(0L)).isEqualTo(60_000L);

		assertThat(kills).hasValue(0);
		assertThat(messages).singleElement().asString().contains("file store unavailable");
	}

	@Test
	void keepsCheckingWhenNoLocationIsReadable() {
		DiskSpaceMonitor monitor = new DiskSpaceMonitor(messages::add, kills::incrementAndGet, () -> null)
				.watch(temporaryDirectory);

		assertThat(monitor.check(0L)).isEqualTo(60_000L);

		assertThat(kills).hasValue(0);
		assertThat(messages).hasSize(1);
	}

	/**
	 * Guessing at a volume before the run says where it writes could kill a load over a full disk it never touches, so
	 * an unconfigured monitor watches nothing and comes back quickly rather than reporting or acting on a guess.
	 */
	@Test
	void staysQuietAndLooksAgainSoonWhileNothingIsWatchedYet() {
		DiskSpaceMonitor monitor = new DiskSpaceMonitor(messages::add, kills::incrementAndGet, null);

		assertThat(monitor.check(0L)).isEqualTo(1_000L);

		assertThat(kills).hasValue(0);
		assertThat(messages).isEmpty();
	}

	@Test
	void readsTheFileSystemForALocationThatDoesNotExistYet() throws IOException {
		DiskSpaceMonitor monitor = new DiskSpaceMonitor(messages::add, kills::incrementAndGet, null)
				.watch(temporaryDirectory.resolve("store").resolve("not-created-yet"));

		DiskSpaceMonitor.Reading reading = monitor.tightestReading();

		assertThat(reading).isNotNull();
		assertThat(reading.usableBytes()).isPositive();
	}

	@Test
	void watchingReplacesTheLocationsItWasStartedWith() {
		Path store = temporaryDirectory.resolve("store");

		DiskSpaceMonitor monitor = new DiskSpaceMonitor(messages::add, kills::incrementAndGet, null)
				.watch(temporaryDirectory)
				.watch(store, null);

		assertThat(monitor.watchedLocations()).containsExactly(store.toAbsolutePath().normalize());
	}

	@Test
	void keepsTheEarlierLocationsWhenThereIsNothingToReplaceThemWith() {
		DiskSpaceMonitor monitor = new DiskSpaceMonitor(messages::add, kills::incrementAndGet, null)
				.watch(temporaryDirectory)
				.watch((Path) null);

		assertThat(monitor.watchedLocations()).containsExactly(temporaryDirectory.toAbsolutePath().normalize());
	}

	@Test
	void monitorsOnADaemonThreadThatStopsWhenClosed() throws Exception {
		CountDownLatch checked = new CountDownLatch(2);
		DiskSpaceMonitor monitor = new DiskSpaceMonitor(messages::add, kills::incrementAndGet, () -> {
			checked.countDown();
			return new DiskSpaceMonitor.Reading("/dev/test", 60 * GIB);
		}).start();
		try {
			assertThat(checked.await(30L, TimeUnit.SECONDS)).isTrue();
			assertThat(monitor.monitoringThread().isDaemon()).isTrue();
		} finally {
			monitor.close();
		}

		assertThat(monitor.monitoringThread().isAlive()).isFalse();
		assertThat(kills).hasValue(0);
	}

	private DiskSpaceMonitor monitorOver(long usableBytes) {
		return new DiskSpaceMonitor(messages::add, kills::incrementAndGet,
				() -> new DiskSpaceMonitor.Reading("/dev/test", usableBytes));
	}
}
